old:
# 定义集体变量
colvar {
    name distance_cv
    distance {
        group1 { atomNumbers 100 }
        group2 { atomNumbers 200 }
    }
    width 0.01   # 分箱宽度 (nm)
}

# ABF 设置
abf {
    colvars distance_cv
    lowerBoundary 0.20
    upperBoundary 1.00
    bins 80
    fullSamples 200       # 每箱至少 200 个样本后才开始偏置
    outputFreq 1000
}

# 输出
output {
    colvar_freq 100
    file colvar.dat
    statFile colvar.stat
}

new:
# GROMACS 后端使用原生单位：距离 nm、能量 kJ/mol
units gromacs

# 两个 atomNumbers 必须对应当前拓扑/坐标中的原子编号
colvar {
    name distance_cv
    distance {
        group1 { atomNumbers 100 }
        group2 { atomNumbers 200 }
    }
    lowerBoundary 0.20
    upperBoundary 1.00
    width 0.01   # nm；该范围对应 80 个网格间隔
}

# ABF 的 colvars 在此引用上面定义的 CV；网格边界/宽度属于 colvar 块
abf {
    name abf
    colvars distance_cv
    fullSamples 200
    outputFreq 1000
}

# Colvars 将轨迹写为 &lt;GROMACS 输出前缀&gt;.colvars.traj；
# ABF 的 PMF/梯度/计数文件按输出前缀命名
